var path=[],pathAjax=(path=location.toString().split("/"))[3];function inter_init(){var e=document.getElementById("searchform-order"),e=e[e.selectedIndex].value;$.ajax({url:"http://192.168.1.1/yii2-consumption/json/outlayadmin/ajaxhandler",type:"POST",data:{order:e,param2:"",_csrf:yii.getCsrfToken()},dataType:"json",success:function(e){var t,r,o=new Array;for([t,r]of Object.entries(e))o.push({value:""+t,text:""+r});createPoleSelect(o)},error:function(e,t,r){console.error(e.responseText)}})}function createPoleSelect(e){var t=document.getElementById("searchform-pole");for(o=t.options.length-1;0<=o;o--)t.remove(o);var r=document.createElement("option");r.textContent="",r.value="",r.selected=!0,t.appendChild(r);for(var o=0;o<e.length;o++){var n=document.createElement("option");n.text=e[o].text,n.value=e[o].value,t.options.add(n)}}function changeOrder(){var e=document.getElementById("searchform-order"),e=e[e.selectedIndex].value;$.ajax({url:"http://192.168.1.1/yii2-consumption/json/outlay/ajaxhandler",type:"POST",data:{order:e,param2:"",_csrf:yii.getCsrfToken()},dataType:"json",success:function(e){var t,r,o=new Array;for([t,r]of Object.entries(e))o.push({value:""+t,text:""+r});createPoleSelect(o)},error:function(e,t,r){console.error(e.responseText)}})}window.onload=inter_init;